<script setup lang="ts">
import {computed,ref,onUnmounted} from 'vue';
import UiIcon from './UiIcon.vue';
const tab=ref<'request'|'response'>('request'),stage=ref(0),running=ref(false),copied=ref(false),gate=ref(0);
const base=import.meta.env.BASE_URL;
const request='GET /api/cases/42 HTTP/1.1\nHost: demo.example\nCookie: session=demo\nUser-Agent: Mozilla/5.0';
const response='HTTP/1.1 200 OK\nContent-Type: application/json\n\n{ "id": 42, "status": "open" }';
const code=computed(()=>tab.value==='request'?request:response);
const gates=[{title:'身分',icon:'user' as const,text:'驗證你是誰',detail:'伺服器驗證 Session，確認這次請求的使用者身分。'},{title:'權限',icon:'shield' as const,text:'檢查可否存取',detail:'已登入仍需檢查是否能讀取案件 42，不能只依賴前端隱藏按鈕。'},{title:'資料',icon:'database' as const,text:'讀取或處理資料',detail:'通過身分與權限檢查後，才讀取允許回傳的案件欄位。'}];
let timer:ReturnType<typeof setTimeout>|undefined;let copyTimer:ReturnType<typeof setTimeout>|undefined;
function play(){clearTimeout(timer);running.value=true;stage.value=1;tab.value='request';timer=setTimeout(()=>{stage.value=2;timer=setTimeout(()=>{stage.value=3;tab.value='response';timer=setTimeout(()=>{running.value=false;},900);},1200);},1200);}
async function copy(){try{await navigator.clipboard.writeText(code.value);copied.value=true;clearTimeout(copyTimer);copyTimer=setTimeout(()=>copied.value=false,1800);}catch{copied.value=false;}}
onUnmounted(()=>{clearTimeout(timer);clearTimeout(copyTimer);});
</script>
<template><div class="lesson-grid http-lesson"><section class="lesson-main"><div class="network-stage" :class="`stage-${stage}`"><div class="client-object"><img :src="`${base}assets/browser.webp`" alt="淺銀色筆電與瀏覽器圖示"><h2>瀏覽器</h2><p>Client / Browser<br>發送 HTTP 請求</p></div><div class="packet-routes"><button class="route-label request-label" @click="tab='request'"><strong>Request 請求</strong><small>GET /api/cases/42</small></button><div class="packet-line outbound" aria-hidden="true"><span class="packet"><UiIcon name="right" :size="15"/></span><UiIcon name="right"/></div><div class="packet-line inbound" aria-hidden="true"><UiIcon name="left"/><span class="packet"><UiIcon name="left" :size="15"/></span></div><button class="route-label response-label" @click="tab='response'"><strong>Response 回應</strong><small>HTTP/1.1 200 OK</small></button></div><div class="server-object"><img :src="`${base}assets/server.webp`" alt="立體線框伺服器"><div class="server-label"><h2>伺服器</h2><p>Web Server</p></div><div class="server-gates"><button v-for="(item,i) in gates" :key="item.title" :aria-pressed="gate===i" @click="gate=i"><UiIcon :name="item.icon" :size="32"/><strong>{{item.title}}</strong><small>{{item.text}}</small></button></div></div></div><div class="simulation-controls"><button class="play-button" :disabled="running" @click="play"><UiIcon name="play" :size="18"/>{{running?'演示中':'播放封包流程'}}</button><span role="status">{{['點選身分、權限或資料，查看伺服器的檢查。','1 / 3 瀏覽器送出請求','2 / 3 伺服器驗證並讀取資料','3 / 3 回應送回瀏覽器'][stage]}}</span></div><p class="gate-explanation"><strong>{{gates[gate].title}}：</strong>{{gates[gate].detail}}</p><details class="practice"><summary><UiIcon name="lab" :size="25"/><span>練習：觀察一次 API 請求<small>在 Network 找到 Method、Header、Body、Status Code。</small></span><UiIcon name="right" :size="18"/></summary><p>在自己的測試站開啟開發者工具 → Network，操作查詢功能。點選該請求，對照 Headers 與 Response，找出身分憑證放在哪裡；分享截圖前先遮蔽 Cookie。</p></details></section><aside class="inspector"><slot/><div class="inspector-tabs" role="tablist" aria-label="HTTP 封包"><button id="request-tab" role="tab" :aria-selected="tab==='request'" aria-controls="packet-panel" @click="tab='request'">Request</button><button id="response-tab" role="tab" :aria-selected="tab==='response'" aria-controls="packet-panel" @click="tab='response'">Response</button></div><section id="packet-panel" role="tabpanel" :aria-labelledby="`${tab}-tab`"><h2>HTTP {{tab==='request'?'請求':'回應'}}範例</h2><p>{{tab==='request'?'瀏覽器送出的原始 HTTP 請求。':'伺服器處理完成後回傳的結果。'}}</p><div class="code-block"><button :aria-label="copied?'已複製':'複製封包內容'" @click="copy"><UiIcon :name="copied?'check':'copy'" :size="19"/></button><pre>{{code}}</pre></div><h3>{{tab==='request'?'請求':'回應'}}重點</h3><dl v-if="tab==='request'"><div><dt>方法</dt><dd>GET　（讀取資源）</dd></div><div><dt>路徑</dt><dd>/api/cases/42</dd></div><div><dt>主機</dt><dd>demo.example</dd></div><div><dt>Cookie</dt><dd>session=demo <small>（範例憑證）</small></dd></div></dl><dl v-else><div><dt>狀態</dt><dd>200 OK（成功）</dd></div><div><dt>格式</dt><dd>application/json</dd></div><div><dt>內容</dt><dd>案件 42 的允許欄位</dd></div></dl><div class="takeaway"><UiIcon name="info" :size="24"/><div><strong>前端限制，需要伺服器端驗證</strong><p>前端可以控制介面行為，但每次請求仍需在伺服器端驗證身分與權限。</p></div></div></section></aside></div></template>
